head.b:skin:
* { box-sizing: border-box; }
html { min-height: 100%; background: #101827; }
body {
  margin: 0; min-height: 100vh; background: #101827; color: #f8fafc;
  font-family: Arial, Helvetica, sans-serif; -webkit-text-size-adjust: 100%;
}
button { font: inherit; }
#reward-app { width: 100%; max-width: 520px; min-height: 100vh; margin: 0 auto; padding: 18px 16px 104px; }
.topbar { display:flex; align-items:center; justify-content:space-between; margin: 4px 0 25px; }
.brand { font-size:22px; font-weight:800; letter-spacing:-.5px; }
.brand span { color:#39d98a; }
.avatar { width:42px; height:42px; border-radius:50%; display:grid; place-items:center; background:#26354c; font-size:21px; }
.welcome { margin-bottom:18px; }
.welcome h1 { margin:0 0 7px; font-size:23px; line-height:1.3; }
.welcome p { margin:0; color:#9aabc0; font-size:13px; }
.balance-card { padding:23px; border-radius:20px; margin-bottom:15px; background:linear-gradient(135deg,#176b52,#123e46); box-shadow:0 12px 30px rgba(0,0,0,.18); }
.muted-light { color:#d1fae5; font-size:13px; }
.balance-number { margin:12px 0; font-size:36px; line-height:1.2; font-weight:800; overflow-wrap:anywhere; }
.balance-number small { font-size:14px; font-weight:500; }
.balance-foot { display:flex; justify-content:space-between; gap:8px; color:#c3f6dd; font-size:12px; }
.stats { display:grid; grid-template-columns:1fr 1fr; gap:12px; margin:0 0 25px; }
.stat { padding:16px; border:1px solid #29394e; border-radius:15px; background:#1b283a; min-width:0; }
.stat-icon { font-size:21px; margin-bottom:10px; }
.stat-label { color:#9aabc0; font-size:12px; margin-bottom:7px; }
.stat-value { font-size:21px; font-weight:800; overflow-wrap:anywhere; }
.section-title { margin:0 0 13px; font-size:18px; font-weight:700; }
.reward-card { margin-bottom:22px; padding:22px; border:1px solid #29394e; border-radius:18px; background:#1b283a; text-align:center; }
.gift-icon { width:76px; height:76px; display:grid; place-items:center; margin:0 auto 15px; border-radius:22px; background:#203e39; font-size:38px; }
.reward-card h2 { margin:0 0 8px; font-size:20px; }
.reward-card p { margin:0 0 19px; color:#9aabc0; font-size:13px; line-height:1.6; }
.claim-btn { width:100%; min-height:50px; padding:14px 16px; border:0; border-radius:13px; background:linear-gradient(135deg,#31dc91,#13b978); color:#062e22; font-size:16px; font-weight:800; cursor:pointer; }
.claim-btn:disabled { opacity:.55; cursor:not-allowed; }
#appNotice { display: none !important; }
.notice { margin-bottom:21px; padding:13px; border-radius:12px; background:#202f43; color:#b5c4d7; font-size:12px; line-height:1.65; overflow-wrap:anywhere; }
.history { padding:15px; border:1px solid #29394e; border-radius:16px; background:#1b283a; }
.history-row { display:flex; justify-content:space-between; align-items:center; gap:10px; padding:12px 0; border-bottom:1px solid #304057; }
.history-row:last-child { border-bottom:0; }
.history-left { display:flex; align-items:center; gap:10px; min-width:0; }
.history-icon { width:38px; height:38px; flex:0 0 38px; display:grid; place-items:center; border-radius:12px; background:#21483d; }
.history-name { font-size:13px; font-weight:700; }
.history-date { margin-top:5px; color:#9aabc0; font-size:11px; overflow-wrap:anywhere; }
.history-amount { color:#3ce49b; font-size:13px; font-weight:800; white-space:nowrap; }
.empty { padding:19px 4px; color:#9aabc0; font-size:13px; text-align:center; }
.page { display:none; }
.page.active { display:block; }
.bottom-nav { position:fixed; z-index:20; bottom:0; left:50%; transform:translateX(-50%); width:100%; max-width:520px; display:flex; justify-content:space-around; padding:11px 8px calc(11px + env(safe-area-inset-bottom)); border-top:1px solid #29394e; background:#182438; }
.nav-item { min-width:65px; padding:2px 8px; color:#8292a9; text-align:center; font-size:11px; cursor:pointer; }
.nav-item.active { color:#38dc91; }
.nav-icon { display:block; margin-bottom:4px; font-size:21px; }
#toast { position:fixed; z-index:50; bottom:85px; left:50%; transform:translateX(-50%); display:none; width:calc(100% - 32px); max-width:450px; padding:13px 15px; border-radius:12px; background:#26364b; color:#fff; box-shadow:0 5px 20px rgba(0,0,0,.3); text-align:center; font-size:13px; line-height:1.5; }
.profile-box { padding:20px; border-radius:17px; background:#1b283a; border:1px solid #29394e; overflow-wrap:anywhere; }
.profile-label { color:#9aabc0; font-size:12px; margin-bottom:7px; }
.profile-value { font-size:20px; font-weight:700; margin-bottom:18px; }

.withdraw-card { padding:18px; border:1px solid #29394e; border-radius:18px; background:#1b283a; margin-bottom:18px; }
.withdraw-card label { display:block; margin:13px 0 7px; color:#b8c6d8; font-size:13px; }
.withdraw-card input, .withdraw-card select { width:100%; min-height:48px; padding:12px; border:1px solid #3a4b62; border-radius:11px; background:#101d2e; color:#f8fafc; font:inherit; outline:none; }
.withdraw-card input:focus, .withdraw-card select:focus { border-color:#39d98a; }
.withdraw-help { color:#9aabc0; font-size:12px; line-height:1.6; margin-top:10px; }
.withdraw-submit { width:100%; min-height:49px; margin-top:17px; border:0; border-radius:12px; background:linear-gradient(135deg,#31dc91,#13b978); color:#062e22; font-weight:800; cursor:pointer; }
.withdraw-submit:disabled { opacity:.55; cursor:not-allowed; }

@media (min-width:600px) {
  body { padding:20px 0; }
  #reward-app { min-height:calc(100vh - 40px); border:1px solid #29394e; border-radius:22px; }
  .bottom-nav { bottom:20px; border-radius:0 0 22px 22px; }
}

body.script:
//
var APP_CONFIG = {
  ZONE_ID: "12224128",
  MONETAG_SDK_URL: "https://libtl.com/sdk.js",
  REWARD_AMOUNT: 10,
  CURRENCY_NAME: "Coins",
  API_BASE_URL: "https://YOUR-DOMAIN.COM/api",
  PROFILE_ENDPOINT: "/profile.php",
  START_CLAIM_ENDPOINT: "/claim-start.php",
  HISTORY_ENDPOINT: "/history.php",
  TELEGRAM_BOT_USERNAME: "HPStore67_bot"
};
//

//
(function () {
  "use strict";

  var C = window.APP_CONFIG;
  var tg = window.Telegram && window.Telegram.WebApp ? window.Telegram.WebApp : null;
  var busy = false;
  var sdkPromise = null;

  function byId(id) { return document.getElementById(id); }

  function showToast(message) {
    var el = byId("toast");
    if (!el) return;
    el.textContent = message;
    el.style.display = "block";
    if (showToast.timer) window.clearTimeout(showToast.timer);
    showToast.timer = window.setTimeout(function () {
      el.style.display = "none";
    }, 4000);
  }

  function numberText(value) {
    var n = Number(value);
    return isFinite(n) ? n.toLocaleString() : "0";
  }

  function escapeText(value) {
    return String(value == null ? "" : value).replace(/[&<>"']/g, function (ch) {
      return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch];
    });
  }

  function apiConfigured() {
    return C.API_BASE_URL && C.API_BASE_URL.indexOf("YOUR-DOMAIN") === -1;
  }

  function telegramInitData() {
    return tg && tg.initData ? tg.initData : "";
  }

  async function request(path, method, payload) {
    if (!apiConfigured()) {
      throw new Error("আপনার API_BASE_URL সেট করা হয়নি।");
    }
    var headers = {"Content-Type":"application/json"};
    headers["X-Telegram-Init-Data"] = telegramInitData();

    var options = {
      method: method || "GET",
      headers: headers,
      credentials: "include"
    };

    if (payload) {
      payload.initData = telegramInitData();
      options.body = JSON.stringify(payload);
    }

    var response = await fetch(C.API_BASE_URL.replace(/\/+$/, "") + path, options);
    var result;
    try { result = await response.json(); }
    catch (e) { throw new Error("Backend থেকে সঠিক JSON পাওয়া যায়নি।"); }

    if (!response.ok || result.success === false) {
      throw new Error(result.message || ("Server error " + response.status));
    }
    return result;
  }

  function renderHistory(targetId, items) {
    var target = byId(targetId);
    if (!target) return;
    if (!Array.isArray(items) || !items.length) {
      target.innerHTML = "<div class='empty'>No transactions yet.</div>";
      return;
    }
    var html = "";
    items.forEach(function (item) {
      var amount = numberText(item.amount || 0);
      var date = escapeText(item.created_at || item.date || "");
      html += "<div class='history-row'>" +
        "<div class='history-left'><div class='history-icon'>🎁</div>" +
        "<div><div class='history-name'>Reward Claim</div><div class='history-date'>" + date + "</div></div></div>" +
        "<div class='history-amount'>+" + amount + "</div></div>";
    });
    target.innerHTML = html;
  }

  function updateProfile(data) {
    data = data || {};
    byId("balanceAmount").textContent = numberText(data.balance);
    byId("withdrawBalance").textContent = numberText(data.balance);
    byId("withdrawCurrency").textContent = C.CURRENCY_NAME;
    byId("balanceCurrency").textContent = C.CURRENCY_NAME;
    byId("totalClaims").textContent = numberText(data.total_claims);
    byId("todayEarnings").textContent = numberText(data.today_earnings);
    byId("userName").textContent = data.name || "User";
    byId("profileName").textContent = data.name || "User";
    byId("profileId").textContent = data.user_id || "Connected";
  }

  async function loadDashboard() {
    if (!apiConfigured()) {
      byId("appNotice").textContent =
        "ডিজাইন দেখা যাচ্ছে। আসল Balance ও History চালু করতে APP_CONFIG-এ API_BASE_URL বসান।";
      renderHistory("homeHistory", []);
      renderHistory("fullHistory", []);
      return;
    }

    try {
      var profileResult = await request(C.PROFILE_ENDPOINT, "GET");
      updateProfile(profileResult.user || profileResult);

      var historyResult = await request(C.HISTORY_ENDPOINT, "GET");
      var rows = historyResult.items || historyResult.history || [];
      renderHistory("homeHistory", rows.slice(0, 5));
      renderHistory("fullHistory", rows);
      byId("appNotice").textContent = "আপনার Account ও Balance Backend থেকে লোড হয়েছে।";
    } catch (error) {
      console.error("Dashboard API:", error);
      byId("appNotice").textContent =
        "Dashboard দেখা যাচ্ছে, কিন্তু Backend সংযোগ হয়নি: " + error.message;
    }
  }

  function loadMonetag() {
    if (sdkPromise) return sdkPromise;

    sdkPromise = new Promise(function (resolve, reject) {
      var sdkFunction = "show_" + C.ZONE_ID;

      if (typeof window[sdkFunction] === "function") {
        resolve(window[sdkFunction]);
        return;
      }

      var script = document.createElement("script");
      script.async = true;
      script.src = C.MONETAG_SDK_URL;
      script.setAttribute("data-zone", C.ZONE_ID);
      script.setAttribute("data-sdk", sdkFunction);

      script.onload = function () {
        if (typeof window[sdkFunction] === "function") {
          resolve(window[sdkFunction]);
        } else {
          sdkPromise = null;
          reject(new Error("Monetag SDK function পাওয়া যায়নি। Zone ID ও SDK code যাচাই করুন।"));
        }
      };

      script.onerror = function () {
        sdkPromise = null;
        reject(new Error("Monetag SDK load হয়নি।"));
      };

      document.head.appendChild(script);
    });

    return sdkPromise;
  }

  async function claimReward() {
    if (busy) return;

    if (!tg || !telegramInitData()) {
      showToast("Telegram Mini App থেকে Open করুন।");
      return;
    }

    if (!apiConfigured()) {
      showToast("প্রথমে APP_CONFIG-এ Backend API URL বসান।");
      return;
    }

    busy = true;
    var button = byId("claimButton");
    button.disabled = true;
    button.textContent = "PLEASE WAIT...";

    try {
      var start = await request(C.START_CLAIM_ENDPOINT, "POST", {
        zone_id: C.ZONE_ID
      });

      if (!start.ymid) {
        throw new Error("Backend থেকে claim ymid পাওয়া যায়নি।");
      }

      var showAd = await loadMonetag();
      showToast("বিজ্ঞাপন লোড হচ্ছে...");

      var result = await showAd({
        type: "end",
        ymid: String(start.ymid),
        requestVar: "claim_reward"
      });

      if (result && result.reward_event_type === "valued") {
        showToast("Reward event পাওয়া গেছে। Balance আপডেট হচ্ছে...");
        await new Promise(function (resolve) { window.setTimeout(resolve, 1800); });
        await loadDashboard();
      } else {
        showToast("এই বিজ্ঞাপনে valued reward পাওয়া যায়নি। Balance যোগ হয়নি।");
      }
    } catch (error) {
      console.error("Claim error:", error);
      showToast(error.message || "Claim সম্পন্ন হয়নি।");
    } finally {
      busy = false;
      button.disabled = false;
      button.textContent = "▶ CLAIM REWARD";
    }
  }


  async function submitWithdraw(event) {
    event.preventDefault();
    var button = byId("withdrawSubmit");
    if (!tg || !telegramInitData()) {
      showToast("Telegram Mini App থেকে Withdraw করুন।");
      return;
    }
    var method = byId("withdrawMethod").value;
    var amount = Number(byId("withdrawAmount").value);
    var phone = byId("withdrawNumber").value.trim();
    if (!method || !Number.isFinite(amount) || amount < 100 || !/^01[3-9]\d{8}$/.test(phone)) {
      showToast("Method, কমপক্ষে 100 Coins এবং সঠিক ১১ ডিজিটের নম্বর দিন।");
      return;
    }
    var user = (tg && tg.initDataUnsafe && tg.initDataUnsafe.user) ? tg.initDataUnsafe.user : {};
    var userId = user.id || "Not available";
    var username = user.username ? "@" + user.username : (user.first_name || "Telegram user");
    var message = "WITHDRAW REQUEST\n" +
      "User: " + username + "\n" +
      "Telegram ID: " + userId + "\n" +
      "Method: " + method + "\n" +
      "Amount: " + amount + " Coins\n" +
      "Payment Number: " + phone + "\n" +
      "Status: Pending\n" +
      "Please review this request.";
    var shareUrl = "https://t.me/share/url?url=" + encodeURIComponent("https://t.me/" + C.TELEGRAM_BOT_USERNAME) + "&text=" + encodeURIComponent(message);
    button.disabled = true;
    button.textContent = "OPENING TELEGRAM...";
    try {
      if (tg && typeof tg.openTelegramLink === "function") tg.openTelegramLink(shareUrl);
      else window.open(shareUrl, "_blank", "noopener");
      showToast("Telegram খুলবে। Bot/Admin chat নির্বাচন করে Send করুন।");
      byId("withdrawForm").reset();
    } catch (error) {
      console.error("Telegram share error:", error);
      showToast("Telegram share খুলতে পারেনি। আবার চেষ্টা করুন।");
    } finally {
      button.disabled = false;
      button.textContent = "SUBMIT WITHDRAW REQUEST";
    }
  }

  function showPage(pageId) {
    document.querySelectorAll(".page").forEach(function (page) {
      page.classList.toggle("active", page.id === pageId);
    });
    document.querySelectorAll(".nav-item").forEach(function (item) {
      item.classList.toggle("active", item.getAttribute("data-page") === pageId);
    });
  }

  document.querySelectorAll(".nav-item").forEach(function (item) {
    item.addEventListener("click", function () {
      showPage(item.getAttribute("data-page"));
    });
  });

  byId("claimButton").addEventListener("click", claimReward);
  byId("withdrawForm").addEventListener("submit", submitWithdraw);
  byId("rewardAmount").textContent = numberText(C.REWARD_AMOUNT) + " " + C.CURRENCY_NAME;
  byId("balanceCurrency").textContent = C.CURRENCY_NAME;

  if (tg) {
    try { tg.ready(); tg.expand(); } catch (e) {}
    if (tg.initDataUnsafe && tg.initDataUnsafe.user) {
      var user = tg.initDataUnsafe.user;
      byId("userName").textContent = user.first_name || "User";
    }
  }

  loadDashboard();
})();
//
